update pages set contenu = '{"sections":[{"type":"heros","h1":"Levage industriel et manutention lourde","mecanisme":"**La machine arrive à sa place, intacte, sans que l''atelier s''arrête autour.** Lever une charge, c''est d''abord une méthode, pas un engin.","cta":"Faire chiffrer mon levage","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30"},{"type":"chiffres","chiffres":[{"valeur":"+ 100","libelle":"collaborateurs · techniciens salariés Migen, pas de chaîne d''intermédiaires."},{"valeur":"+ 120","libelle":"clients industriels · dont plus de 80 qui reviennent chaque année."},{"valeur":"4","libelle":"agences · Lyon (siège), Montréal, Dubaï, Madrid, et des hubs techniques en France."},{"valeur":"10 %","libelle":"des candidats retenus · entretien technique et entretien comportemental, résultats partagés avec vous."}],"reponse":[{"texte":"<!-- BLOC E01 : bande de chiffres, 4 items -->"}]},{"type":"probleme","punchline":"Une machine s''abîme rarement en tournant. Elle s''abîme en bougeant.","puces":[{"accroche":"Une masse estimée à l''œil.","texte":"L''élingage est calculé sur un poids supposé, pas sur le poids réel de l''équipement."},{"accroche":"Des points d''élingage inventés.","texte":"Personne n''a lu la notice constructeur ni relevé les points prévus avant la dépose."},{"accroche":"Un accès découvert le matin même.","texte":"Hauteur sous ferme, portée du sol, largeur de porte, passage de caniveau : mesurés trop tard."},{"accroche":"Un atelier arrêté pour rien.","texte":"Faute de coactivité préparée, la zone entière s''immobilise pendant l''opération."}]},{"type":"offre","lignes":[{"prestation":"**Étude de levage préalable**","benefice":"Masse réelle, centre de gravité, points d''élingage constructeur, portée du sol, gabarit d''accès. Les surprises sont traitées sur le papier, pas sous la charge."},{"prestation":"**Mode opératoire écrit**","benefice":"Chaque phase décrite, chaque intervenant à sa place, les zones d''exclusion définies. Vos équipes savent où ne pas être."},{"prestation":"**Élingage et accessoires adaptés**","benefice":"Choix des accessoires selon la charge, la géométrie et les points d''accroche réels. L''accessoire suit la machine, pas l''inverse."},{"prestation":"**Manutention en atelier**","benefice":"Déplacement, ripage, mise en position d''équipements lourds dans des espaces contraints, entre des lignes qui continuent de tourner."},{"prestation":"**Mise en position et calage**","benefice":"Mise à niveau, alignement, ancrage. La qualité du calage conditionne l''usure des années suivantes."},{"prestation":"**Levage pendant un transfert**","benefice":"Dépose et repose des équipements dans le cadre d''un [transfert industriel](/travaux-industriels/transfert-industriel/), par la même équipe qui démonte et remonte."},{"prestation":"**Levage pendant un montage**","benefice":"Mise en place des ensembles lourds au moment du [montage industriel](/travaux-industriels/montage-industriel/), dans l''ordre imposé par le constructeur."},{"prestation":"**Levage pendant un démantèlement**","benefice":"Sortie des charges lors d''un [démantèlement industriel](/travaux-industriels/demantelement-industriel/), par les accès réels du bâtiment."},{"prestation":"**Coordination avec un partenaire de levage**","benefice":"Quand l''opération exige des moyens spécialisés, nous les mobilisons et nous les pilotons. Vous gardez un seul interlocuteur."}],"prose":[{"texte":"<!-- BLOC C02 : tableau prestations / bénéfices -->"}]},{"type":"deroule","etapes":[{"titre":"Relevé sur site.","texte":"Masses, encombrements, points d''élingage, accès, portée des sols, obstacles en hauteur, réseaux enterrés."},{"titre":"Étude et choix des moyens.","texte":"Les moyens sont dimensionnés à partir des relevés. Moyens Migen ou partenaire spécialisé selon la charge et la configuration."},{"titre":"Analyse de risque et plan de prévention.","texte":"Coactivité avec votre production, zones d''exclusion, balisage, conduite à tenir en cas d''aléa."},{"titre":"Préparation de la charge.","texte":"Consignation, vidanges quand elles s''imposent, dépose des éléments fragiles, protections, points d''accroche préparés."},{"titre":"Opération de levage.","texte":"Un chef de manœuvre, des intervenants à poste, des communications définies. Personne n''improvise sous une charge."},{"titre":"Mise en position et contrôle.","texte":"Calage, mise à niveau, alignement, contrôle final avant remise à votre exploitant."}]},{"type":"garanties","puces":[{"accroche":"Rien ne se lève sans relevé.","texte":"Masse, points d''élingage et accès sont vérifiés sur site avant l''intervention. Une masse estimée de mémoire n''est pas une donnée d''entrée."},{"accroche":"La sécurité passe avant le calendrier.","texte":"Analyse de risque, plan de prévention, mode opératoire écrit pour chaque phase, pour vos équipes comme pour les nôtres."},{"accroche":"Le levage n''est pas séparé du reste.","texte":"L''équipe qui lève est celle qui démonte et qui rebranche. C''est ce qui vous évite de payer la couture entre deux prestataires."}]},{"type":"cta","question":"Besoin de déplacer un équipement lourd sans arrêter l''atelier autour ?","bouton":"Faire chiffrer mon levage","href":"/contact/","rappel":"04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30, astreinte 24/24 et 7/7."},{"type":"preuves","preuves":[{"titre":"Montage d''un centre logistique, Clermont-Ferrand, 2023.","texte":"12 monteurs mécaniciens et 8 engins de levage mobilisés sur le chantier, site livré à la date prévue","lienLibelle":"Étude de cas AKTID","lienHref":"/preuves/aktid-centre-logistique/"},{"titre":"Montage de portiques de lavage, partout en France.","texte":"Réception, assemblage, levage et raccordements, portique validé à l''issue du montage","lienLibelle":"Étude de cas ORTHUS x WASHTEC","lienHref":"/preuves/orthus-washtec/"},{"titre":"Montage et déplacement de machines, étanchéité et isolation, 2025.","texte":"Transferts de machines sécurisés, sans casse ni improvisation","lienLibelle":"Étude de cas SOPREMA","lienHref":"/preuves/soprema/"},{"titre":"Construction d''un site de R&D bas carbone, région parisienne.","texte":"Mise en place des installations et raccordements industriels, pilotage Orthus, filiale du groupe","lienLibelle":"Étude de cas ORTHUS x ECOCEM","lienHref":"/preuves/orthus-ecocem/"}]},{"type":"objections","questions":[{"question":"Combien coûte une opération de levage industriel ?","reponse":"Le montant dépend de la masse, de la géométrie de la charge, des accès, de la durée d''immobilisation de la zone et des moyens à mobiliser. Chiffrage sur devis après relevé sur site. Un prix donné au téléphone sans masse réelle ne tient pas."},{"question":"Disposez-vous de vos propres moyens de levage ?","reponse":"Selon l''opération. Certaines manutentions se font avec nos moyens, d''autres exigent des moyens spécialisés que nous mobilisons auprès d''un partenaire et que nous pilotons. Le choix se fait après relevé, pas avant."},{"question":"Louez-vous des engins sans équipe ?","reponse":"Non. Nous vendons une opération de levage préparée et encadrée, pas un engin à l''heure. La valeur est dans le relevé, le mode opératoire et le chef de manœuvre."},{"question":"Peut-on lever pendant que la ligne voisine produit ?","reponse":"Souvent oui, et c''est tout l''objet de la préparation : zones d''exclusion définies, balisage, phasage sur les créneaux qui vous coûtent le moins. La coactivité est traitée dans le plan de prévention."},{"question":"Que se passe-t-il si l''accès s''avère impossible ?","reponse":"La question est tranchée au relevé, pas le jour du levage. Hauteur libre, portée du sol, largeur de passage et cheminement sont vérifiés avant le devis. Quand un accès ne passe pas, nous le disons et nous proposons une autre voie."},{"question":"Qui sont les intervenants sur l''opération ?","reponse":"Des salariés Migen, évalués en entretien technique et en entretien comportemental. Seuls 10 % des candidats sont retenus. Mécaniciens, monteurs, chaudronniers et soudeurs selon la nature de la charge."}]},{"type":"ctaFinal","question":"Besoin d''un relevé avant de décider comment sortir votre machine ?","bouton":"Parler à un chargé d''affaires","href":"/contact/","rappel":"04 78 33 72 05, astreinte 24/24 et 7/7."}]}'::jsonb where path = '/travaux-industriels/levage-manutention/';
